  "faith": "Many traditions welcome a new child with a blessing, a naming, a dedication, a baptism, or a gathering of family and community. Some families say a short prayer or blessing over the baby at bedtime, and let older children say it too. Others mark the day with a family tradition, a song, or a candle. In some homes a new baby stirs big questions, or brings up old hurts with faith or family. Faith can be a comfort or a strain in this season. Whatever your family does, being carried by others in this season is part of the welcome.",
